n NewWithID(\"\")\n112|}\n113|\n114|func newAppWithDriver(d fyne.Driver, id string) fyne.App {\n115|\tnewApp := &fyneApp{uniqueID: id, driver: d, exec: execabs.Command, lifecycle: &app.Lifecycle{}}\n116|\tfyne.SetCurrentApp(newApp)\n117|\tnewApp.settings = loadSettings()\n118|\n119|\tnewApp.prefs = newPreferences(newApp)\n120|\tnewApp.storage = &store{a: newApp}\n121|\tif id != \"\" {\n122|\t\tif pref, ok := newApp.prefs.(interface{ load() }); ok {\n123|\t\t\tpref.load()\n124|\t\t}\n125|\n126|\t\troot, _ := newApp.storage.docRootURI()\n127|\t\tnewApp.storage.Docs = &internal.Docs{RootDocURI: root}\n128|\t} else {\n129|\t\tnewApp.storage.Docs = &internal.Docs{} // an empty impl to avoid crashes\n130|\t}\n131|\n132|\tif !d.Device().IsMobile() {\n133|\t\tnewApp.settings.watchSettings()\n134|\t}\n135|\n136|\trepository.Register(\"http\", intRepo.NewHTTPRepository())\n137|\trepository.Register(\"https\", intRepo.NewHTTPRepository())\n138|\n139|\treturn newApp\n140|}"}], "task_turn": 5, "text": "<summary>Reading app.go interface; will add Metadata() method and AppMetadata struct.</summary>", "synopsis": "Reading app.go interface; will add Metadata() method and AppMetadata struct.", "archive_sequence": 10, "archived_at": 1790740788.2735093}
