func parseHexDigits(hex string) ([]uint8, error) {
	vals := make([]uint8, len(hex))
	for i, ch := range hex {
		var val uint8
		switch {
		case ch >= '0' && ch <= '9':
			val = uint8(ch - '0')
		case ch >= 'a' && ch <= 'f':
			val = uint8(ch - 'a' + 10)
		case ch >= 'A' && ch <= 'F':
			val = uint8(ch - 'A' + 10)
		default:
			return nil, fmt.Errorf("invalid hex digit: %c", ch)
		}
		vals[i] = val
	}
	return vals, nil
}

func loadResourceFromURI(uriStr string) (fyne.Resource, error) {
	uri, err := storage.ParseURI(uriStr)
	if err != nil {
		return nil, err
	}

	reader, err := storage.Reader(uri)
	if err != nil {
		return nil, err
	}
	defer reader.Close()

	data, err := io.ReadAll(reader)
	if err != nil {
		return nil, err
	}

	return fyne.NewStaticResource(uri.Name(), data), nil
}

