// Package desktop provides desktop-specific application functionality.
package desktop

import "fyne.io/fyne/v2"

// App defines the desktop-specific application interface for system tray integration.
// This extends the base fyne.App with platform-specific features like system tray support.
//
// Since: 2.5
type App interface {
	fyne.App

	// SetSystemTrayMenu sets the menu to be displayed when the system tray icon is clicked.
	// Pass nil to remove the system tray menu.
	// Not all platforms support system tray menus.
	SetSystemTrayMenu(menu *fyne.Menu)

	// SetSystemTrayIcon sets the icon to be displayed in the system tray.
	// Pass nil to remove the system tray icon.
	// The icon will be scaled to match the system tray size on the current platform.
	SetSystemTrayIcon(icon fyne.Resource)
}

