// NewAllStrings returns a validator that runs all provided validators in sequence.
// Returns the first error encountered, or nil if all pass.
//
// Since: 2.5
func NewAllStrings(validators ...func(string) error) func(string) error {
	return func(text string) error {
		for _, v := range validators {
			if err := v(text); err != nil {
				return err
			}
		}
		return nil
	}
}

